import SwiftUI

struct FeaturedAchievementsSelectionView: View {

    @ObservedObject var gamificationViewModel: GamificationViewModel

    @Environment(\.dismiss) private var dismiss

    // MARK: - View State

    @State private var selectedAchievementIDs: [UUID] = []

    @State private var isLoading = true

    @State private var showSaveError = false

    // MARK: - Unlocked Achievements

    private var unlockedAchievements: [AchievementProgressResponse] {

        gamificationViewModel.achievements.filter {
            $0.unlocked
        }
    }

    // MARK: - View

    var body: some View {

        List {

            Section {

                Text(
                    "Choose up to three unlocked achievements to display on your profile. Use the arrows to arrange their order."
                )
                .font(.subheadline)
                .foregroundColor(.secondary)
            }

            if isLoading {

                ProgressView("Loading achievements...")

            } else {

                // MARK: - Selected Achievements

                Section(
                    "Featured Badges (\(selectedAchievementIDs.count)/3)"
                ) {

                    if selectedAchievementIDs.isEmpty {

                        Text("No featured achievements selected.")
                            .foregroundColor(.secondary)

                    } else {

                        ForEach(
                            selectedAchievementIDs,
                            id: \.self
                        ) { achievementID in

                            if let achievement = unlockedAchievements.first(
                                where: { $0.id == achievementID }
                            ) {

                                HStack(spacing: 12) {

                                    Image(
                                        systemName: achievement.icon_name
                                    )
                                    .foregroundColor(
                                        tierColor(for: achievement.tier)
                                    )
                                    .frame(width: 30)

                                    VStack(
                                        alignment: .leading,
                                        spacing: 4
                                    ) {

                                        Text(achievement.title)
                                            .font(.subheadline)
                                            .fontWeight(.semibold)

                                        Text(
                                            achievement.tier.capitalized
                                        )
                                        .font(.caption)
                                        .foregroundColor(.secondary)
                                    }

                                    Spacer()

                                    // Move badge up
                                    Button {

                                        moveAchievement(
                                            achievementID,
                                            by: -1
                                        )

                                    } label: {

                                        Image(systemName: "arrow.up")
                                    }
                                    .buttonStyle(.borderless)
                                    .disabled(
                                        selectedAchievementIDs.first == achievementID
                                    )
                                    .accessibilityLabel("Move badge up")

                                    // Move badge down
                                    Button {

                                        moveAchievement(
                                            achievementID,
                                            by: 1
                                        )

                                    } label: {

                                        Image(systemName: "arrow.down")
                                    }
                                    .buttonStyle(.borderless)
                                    .disabled(
                                        selectedAchievementIDs.last == achievementID
                                    )
                                    .accessibilityLabel("Move badge down")
                                }
                                .padding(.vertical, 6)
                            }
                        }
                    }
                }

                // MARK: - Available Achievements

                Section("Unlocked Achievements") {

                    if unlockedAchievements.isEmpty {

                        Text(
                            "You haven't unlocked any achievements yet. Complete activities to earn your first badge!"
                        )
                        .foregroundColor(.secondary)

                    } else {

                        ForEach(unlockedAchievements) { achievement in

                            Button {

                                toggleAchievement(achievement.id)

                            } label: {

                                HStack(spacing: 12) {

                                    Image(
                                        systemName: achievement.icon_name
                                    )
                                    .font(.title2)
                                    .foregroundColor(
                                        tierColor(for: achievement.tier)
                                    )
                                    .frame(width: 40)

                                    VStack(
                                        alignment: .leading,
                                        spacing: 4
                                    ) {

                                        Text(achievement.title)
                                            .font(.headline)

                                        Text(
                                            achievement.tier.capitalized
                                        )
                                        .font(.caption)
                                        .foregroundColor(
                                            tierColor(for: achievement.tier)
                                        )
                                    }

                                    Spacer()

                                    if selectedAchievementIDs.contains(
                                        achievement.id
                                    ) {

                                        Image(
                                            systemName: "checkmark.circle.fill"
                                        )
                                        .foregroundColor(.green)
                                        .font(.title2)

                                    } else {

                                        Image(systemName: "circle")
                                            .foregroundColor(.secondary)
                                            .font(.title2)
                                    }
                                }
                                .padding(.vertical, 6)
                            }
                            .buttonStyle(.plain)
                            .disabled(
                                !selectedAchievementIDs.contains(achievement.id)
                                && selectedAchievementIDs.count >= 3
                            )
                        }
                    }
                }
            }
        }
        .navigationTitle("Featured Achievements")
        .navigationBarTitleDisplayMode(.inline)

        // MARK: - Save Button

        .toolbar {

            ToolbarItem(placement: .topBarTrailing) {

                Button("Save") {

                    Task {

                        let wasSaved =
                            await gamificationViewModel
                                .saveFeaturedAchievements(
                                    selectedAchievementIDs
                                )

                        if wasSaved {

                            dismiss()

                        } else {

                            showSaveError = true
                        }
                    }
                }
                .disabled(
                    isLoading ||
                    gamificationViewModel.isSavingFeaturedAchievements ||
                    gamificationViewModel.achievements.isEmpty ||
                    gamificationViewModel.featuredAchievementsError != nil
                )
            }
        }

        // MARK: - Load Data

        .task {

            isLoading = true

            // Get all achievements and unlock statuses
            await gamificationViewModel.refreshAchievementProgress()

            // Retrieve previously selected badges
            await gamificationViewModel.refreshFeaturedAchievements()

            // Restore the selection in its saved order
            selectedAchievementIDs =
                gamificationViewModel.featuredAchievements.map {
                    $0.achievement_id
                }

            isLoading = false
        }

        // MARK: - Save Error

        .alert(
            "Unable to Save",
            isPresented: $showSaveError
        ) {

            Button("OK", role: .cancel) {}

        } message: {

            Text(
                gamificationViewModel.featuredAchievementsError ??
                "Please try again."
            )
        }

    } // Closes body

    // MARK: - Select or Remove Achievement

    private func toggleAchievement(_ achievementID: UUID) {

        // If selected, remove it
        if let index = selectedAchievementIDs.firstIndex(
            of: achievementID
        ) {

            selectedAchievementIDs.remove(at: index)

        } else {

            // Add only if fewer than 3 badges are selected
            guard selectedAchievementIDs.count < 3 else {
                return
            }

            selectedAchievementIDs.append(achievementID)
        }
    }

    // MARK: - Change Display Order

    private func moveAchievement(
        _ achievementID: UUID,
        by offset: Int
    ) {

        guard let currentIndex =
                selectedAchievementIDs.firstIndex(
                    of: achievementID
                ) else {

            return
        }

        let newIndex = currentIndex + offset

        guard selectedAchievementIDs.indices.contains(newIndex) else {
            return
        }

        selectedAchievementIDs.swapAt(
            currentIndex,
            newIndex
        )
    }

    // MARK: - Achievement Tier Color

    private func tierColor(for tier: String) -> Color {

        switch tier {

        case "bronze":
            return .brown

        case "silver":
            return .gray

        case "gold":
            return .yellow

        default:
            return .secondary
        }
    }

} // Closes FeaturedAchievementsSelectionView


